//! Keeps `packages/webmcpx/src/generated.js` in sync with the Rust contracts.
//! Run `just gen` (sets `UPDATE_GENERATED=1`) after changing a contract.

use std::path::Path;

use webmcpx_core::{Code, limits, unicode};
use webmcpx_std::tools::ALL;

fn render() -> String {
    let mut out = String::from(
        "// @generated by `just gen` from crates/webmcpx-std. Do not edit.\n\nexport const TOOLS = {\n",
    );
    for tool in ALL {
        out.extend(["  ", tool.name, ": ", &tool.to_json(), ",\n"]);
    }
    out.push_str("};\n\n/** Error code -> retryable. */\nexport const CODES = {\n");
    for code in Code::ALL {
        out.extend([
            "  ",
            code.as_str(),
            ": ",
            if code.retryable() { "true" } else { "false" },
            ",\n",
        ]);
    }
    out.push_str("};\n\n/** Authoring limits, in chars (webmcpx-core `limits`). */\nexport const LIMITS = {\n");
    for (key, value) in [
        ("NAME_WARN", limits::NAME_WARN),
        ("DESCRIPTION_WARN", limits::DESCRIPTION_WARN),
        ("TOOLS_WARN", limits::TOOLS_WARN),
        ("OUTPUT_MAX", limits::OUTPUT_MAX),
    ] {
        out.extend(["  ", key, ": ", &value.to_string(), ",\n"]);
    }
    out.push_str("};\n\n");
    // The invisible set as a regex, so JS strips exactly what Rust strips: an emoji joiner is kept right
    // after a pictograph (`unicode::invisible_chars`).
    let class = |keep: fn(char) -> bool| {
        let mut out = String::new();
        let mut run: Option<(u32, u32)> = None;
        let mut flush = |run: Option<(u32, u32)>, out: &mut String| {
            if let Some((a, b)) = run {
                out.push_str(&format!("\\u{{{a:X}}}"));
                if b > a {
                    out.push_str(&format!("-\\u{{{b:X}}}"));
                }
            }
        };
        for c in (0..=0x10_FFFF).filter_map(char::from_u32) {
            let u = c as u32;
            if keep(c) {
                run = match run {
                    Some((a, b)) if b + 1 == u => Some((a, u)),
                    other => {
                        flush(other, &mut out);
                        Some((u, u))
                    }
                };
            }
        }
        flush(run, &mut out);
        out
    };
    let picto = class(unicode::is_pictograph);
    let joiners = class(unicode::joins_emoji);
    let rest = class(|c| unicode::is_invisible(c) && !unicode::joins_emoji(c));
    out.push_str(&format!(
        "/** Invisible characters (webmcpx-core `unicode`): strip with `s.replace(INVISIBLE, \"\")`. */\nexport const INVISIBLE = new RegExp(\"(?<![{picto}])[{joiners}]|[{rest}]\", \"gu\");\n"
    ));
    out
}

#[test]
fn generated_js_is_up_to_date() {
    let path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../packages/webmcpx/src/generated.js");
    let expected = render();
    if std::env::var_os("UPDATE_GENERATED").is_some() {
        std::fs::write(&path, &expected).unwrap();
        return;
    }
    let actual = std::fs::read_to_string(&path).unwrap_or_default();
    assert!(
        actual == expected,
        "{} is stale: run `just gen`",
        path.display()
    );
}

#[test]
fn contracts_are_valid() {
    for tool in ALL {
        assert_eq!(
            webmcpx_core::validate_name(tool.name),
            Ok(()),
            "{}",
            tool.name
        );
        let schema: serde_json::Value = serde_json::from_str(tool.input_schema).unwrap();
        assert_eq!(schema["type"], "object", "{}", tool.name);
        let def: serde_json::Value = serde_json::from_str(&tool.to_json()).unwrap();
        assert_eq!(def["name"], tool.name);
    }
}
